use vstd::prelude::*;

verus! {
    fn rjust(orig: Vec<char>, width: u8, fillchar: char) -> (res: Vec<char>)
        requires
            width <= 255,
        ensures
            res.len() == max(orig.len(), width as usize),
            if orig.len() < width as usize {
                let padding_len = (width as usize) - orig.len();
                forall(|i: usize| 0 <= i < padding_len ==> res[i] == fillchar) &&
                res[padding_len..] == orig[..]
            } else {
                res == orig
            },
    {
        let orig_len = orig.len();
        let target_len = max(orig_len, width as usize);
        let mut res: Vec<char> = Vec::with_capacity(target_len);
        
        // Fill with the fill character if padding is needed
        if orig_len < width as usize {
            let padding_len = (width as usize) - orig_len;
            for _ in 0..padding_len {
                res.push(fillchar);
            }
        }
        
        // Append the original characters
        for i in 0..orig_len {
            res.push(orig[i]);
        }
        
        // Ensure the result has the correct length
        assert(res.len() == target_len);
        
        res
    }
}
